//! Bundled skills embedded into the binary at compile time.
//!
//! The `build.rs` script collects all `skills/*/SKILL.md` files into
//! `embedded_skills.json`. This module deserializes that blob and provides
//! the raw (name, content) pairs to the skill registry for discovery.

use std::sync::OnceLock;

/// Raw JSON generated by build.rs from `skills/*/SKILL.md`.
const EMBEDDED_SKILLS_JSON: &str = include_str!(concat!(env!("OUT_DIR"), "/embedded_skills.json"));

#[derive(serde::Deserialize)]
struct EmbeddedSkillEntry {
    name: String,
    content: String,
}

/// Parsed bundled skills cached across calls.
fn parsed_skills() -> &'static Vec<(String, String)> {
    static CACHE: OnceLock<Vec<(String, String)>> = OnceLock::new();
    CACHE.get_or_init(|| {
        let entries: Vec<EmbeddedSkillEntry> = match serde_json::from_str(EMBEDDED_SKILLS_JSON) {
            Ok(v) => v,
            Err(e) => {
                tracing::warn!("Failed to parse embedded skills catalog: {}", e);
                return Vec::new();
            }
        };
        entries.into_iter().map(|e| (e.name, e.content)).collect()
    })
}

/// Load all bundled skill (name, content) pairs compiled into the binary.
///
/// Returns a slice of `(skill_name, skill_md_content)` tuples. These are
/// loaded by the skill registry as the lowest-priority discovery source
/// with `Trusted` trust level (they ship with the application).
pub fn load_bundled_skills() -> &'static [(String, String)] {
    parsed_skills()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Skills that must never ship in the bundled tenant catalog again.
    /// Removed per WI#185: contributor-dev workflows (proprietary browser
    /// extensions, Chrome MCP, PR checklists) are not tenant capabilities.
    const REMOVED_DEV_SKILLS: &[&str] = &["web-ui-test", "local-test", "review-checklist"];

    #[test]
    fn bundled_catalog_is_exactly_the_product_skill_set() {
        let bundled: Vec<&str> = load_bundled_skills()
            .iter()
            .map(|(name, _)| name.as_str())
            .collect();

        for removed in REMOVED_DEV_SKILLS {
            assert!(
                !bundled.contains(removed),
                "skill '{removed}' was removed from the bundled tenant catalog by WI#185 \
                 but is embedded again; contributor-dev skills must not ship to tenants"
            );
        }

        let expected = [
            "cavepony",
            "delegation",
            "lunarwing-workflow-orchestrator",
            "multica-poll",
            "plan-mode",
            "routine-advisor",
            "study-notes",
        ];
        let mut actual = bundled.clone();
        actual.sort_unstable();
        assert_eq!(
            actual, expected,
            "bundled skill catalog changed; if this is deliberate, update the expected list \
             and the WI#185 record"
        );
    }

    #[test]
    fn cavepony_is_bundled_and_parseable() {
        let (_, content) = load_bundled_skills()
            .iter()
            .find(|(name, _)| name == "cavepony")
            .expect("Cavepony skill should be embedded");
        let parsed = crate::skills::parser::parse_skill_md(content)
            .expect("embedded Cavepony skill should parse");

        assert_eq!(parsed.manifest.name, "cavepony");
        assert_eq!(parsed.manifest.version, "0.4.0");
        assert_eq!(parsed.manifest.activation.max_context_tokens, 1800);
        assert!(
            parsed
                .manifest
                .activation
                .keywords
                .iter()
                .any(|keyword| keyword == "cavepony")
        );
    }

    #[test]
    fn study_notes_is_bundled_and_uses_native_tools() {
        let (_, content) = load_bundled_skills()
            .iter()
            .find(|(name, _)| name == "study-notes")
            .expect("Study Notes skill should be embedded");
        let parsed = crate::skills::parser::parse_skill_md(content)
            .expect("embedded Study Notes skill should parse");

        assert_eq!(parsed.manifest.name, "study-notes");
        assert_eq!(parsed.manifest.version, "3.1.0");
        assert!(
            parsed
                .manifest
                .activation
                .keywords
                .iter()
                .any(|keyword| keyword == "lunarwing")
        );
        // Native knowledge_* tools ship with the daemon, so the skill no
        // longer needs the external study-MCP env gate.
        assert!(
            parsed
                .manifest
                .metadata
                .and_then(|metadata| metadata.openclaw)
                .is_none_or(|openclaw| !openclaw
                    .requires
                    .env
                    .iter()
                    .any(|name| name == "LW2STUDYMCP_HOME"))
        );
        // The skill body must direct agents at the native tools.
        assert!(content.contains("knowledge_submit_note"));
        assert!(content.contains("knowledge_search"));
        assert!(content.contains("knowledge_list_topics"));
        assert!(content.contains("knowledge_update_status"));
    }
}
